 void newConversationMenu(){new AlertDialog.Builder(this).setTitle("بدء محادثة").setItems(new String[]{"محادثة جديدة","رسالة إلى عدة جهات","إنشاء مجموعة جديدة","جهات الاتصال"},(d,which)->{if(which==0)composeDialog();else if(which==1){filter="bulk";render();pickContactsForBulk();}else if(which==2){filter="groups";render();createGroupDialog();}else showContactsDirectory();}).setNegativeButton("إلغاء",null).show();}
 void showContactsDirectory(){try{android.database.Cursor c=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" COLLATE NOCASE ASC");if(c==null){Toast.makeText(this,"تعذر الوصول إلى جهات الاتصال",Toast.LENGTH_SHORT).show();return;}ArrayList<String> labels=new ArrayList<>(),numbers=new ArrayList<>();while(c.moveToNext()){String n=c.getString(0),p=c.getString(1);if(p!=null){labels.add((n==null||n.isEmpty()?p:n+" · "+p));numbers.add(p);}}c.close();if(labels.isEmpty()){Toast.makeText(this,"لا توجد جهات اتصال بأرقام هاتف",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("جهات الاتصال").setItems(labels.toArray(new String[0]),(d,w)->composeDialog(numbers.get(w))).setNegativeButton("إغلاق",null).show();}catch(Exception e){Toast.makeText(this,"تعذر قراءة جهات الاتصال",Toast.LENGTH_LONG).show();}}
 void settingsDialog(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(12,4,12,4);p.addView(tv("HashemSMS · الإعدادات",20));p.addView(tv("التصميم الكحلي والسماوي مع اللمسات الذهبية",14));Button def=button("تعيين كتطبيق SMS الافتراضي");def.setOnClickListener(v->requestDefault());p.addView(def);new AlertDialog.Builder(this).setTitle("إعدادات الرسائل").setView(p).setPositiveButton("تم",null).show();}
 void render(){if(list==null)return;if(unreadTab!=null)unreadTab.setText("غير مقروءة ("+db.countUnreadMessages()+")");if(failedTab!=null)failedTab.setText("تعذر الإرسال ("+db.countFailedMessages()+")");list.removeAllViews();String searchQuery=search==null?"":search.getText().toString().trim();if(search!=null&&search.getVisibility()==View.VISIBLE&&!searchQuery.isEmpty()){searchResults(searchQuery);return;}if(selectingConversations){list.addView(tv("تم تحديد "+selectedConversations.size()+" محادثة",16));LinearLayout actionBar=new LinearLayout(this);Button all=button("تحديد الكل");all.setOnClickListener(v->{selectedConversations.clear();CursorWrapper rows=new CursorWrapper(db.listThreads(filter));while(rows.moveToNext())selectedConversations.add(rows.getString("address"));rows.close();render();});Button act=button("إجراءات المحددة");act.setOnClickListener(v->selectedConversationMenu(v));Button cancel=button("إلغاء");cancel.setOnClickListener(v->finishConversationSelection());actionBar.addView(all,new LinearLayout.LayoutParams(0,-2,1));actionBar.addView(act,new LinearLayout.LayoutParams(0,-2,1));actionBar.addView(cancel,new LinearLayout.LayoutParams(0,-2,1));list.addView(actionBar);}if("trash".equals(filter)){trashScreen();return;}if("starred".equals(filter)){starredScreen();return;}if("bulk".equals(filter)){bulkScreen();return;}if("groups".equals(filter)){groupsScreen();return;}if("rules".equals(filter)){forwardRulesScreen();return;}if("scheduled".equals(filter)){scheduledScreen();return;}if("failed".equals(filter)){failedScreen();return;}CursorWrapper c=new CursorWrapper(db.listThreads(filter));String q=search.getText().toString().trim();int n=0;while(c.moveToNext()){String a=c.getString("address"),body=c.getString("body"),st=c.getString("status");if(!q.isEmpty()&&!a.contains(q)&&!body.contains(q))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);String contact=contactName(a);boolean selected=selectedConversations.contains(a);LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.HORIZONTAL);header.setGravity(Gravity.CENTER_VERTICAL);header.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);TextView a1=tv((selected?"[✓] ":"")+(contact.isEmpty()?a:contact+" · "+a)+(isPinned(a)?" · مثبت":""),17);a1.setTextColor(purple);header.addView(a1,new LinearLayout.LayoutParams(0,-2,1));int unreadCount=countUnreadForAddress(a);if(unreadCount>0){TextView badge=tv(String.valueOf(unreadCount),12);badge.setGravity(Gravity.CENTER);badge.setPadding(8,2,8,2);badge.setTextColor(Color.rgb(3,22,43));badge.setBackground(rounded(Color.rgb(8,217,245),0,20));header.addView(badge,new LinearLayout.LayoutParams(-2,-2));}if(hasFailedInThread(a)){TextView failedBadge=tv("تعذّر الإرسال",11);failedBadge.setTextColor(Color.rgb(255,205,90));failedBadge.setPadding(7,2,7,2);failedBadge.setBackground(rounded(Color.rgb(74,49,24),Color.rgb(255,190,70),14));header.addView(failedBadge,new LinearLayout.LayoutParams(-2,-2));}TextView b=tv(body,16);row.addView(header);row.addView(b);row.setPadding(8,4,8,4);row.setBackground(rounded(selected?Color.rgb(12,72,94):Color.rgb(6,31,57),Color.rgb(20,81,116),18));LinearLayout.LayoutParams rowLp=new LinearLayout.LayoutParams(-1,-2);rowLp.bottomMargin=(int)(7*getResources().getDisplayMetrics().density);row.setOnClickListener(v->{if(selectingConversations){if(selectedConversations.contains(a))selectedConversations.remove(a);else selectedConversations.add(a);render();}else{Intent i=new Intent(this,ConversationActivity.class);i.putExtra("address",a);startActivity(i);}});row.setOnLongClickListener(v->{if(selectingConversations){if(selectedConversations.contains(a))selectedConversations.remove(a);else selectedConversations.add(a);render();}else conversationOptions(v,a);return true;});GestureDetector gestures=new GestureDetector(this,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(android.view.MotionEvent e){return true;}public boolean onSingleTapUp(android.view.MotionEvent e){row.performClick();return true;}public void onLongPress(android.view.MotionEvent e){row.performLongClick();}public boolean onFling(android.view.MotionEvent e1,android.view.MotionEvent e2,float vx,float vy){float dx=e2.getX()-e1.getX();if(Math.abs(dx)<100*getResources().getDisplayMetrics().density||Math.abs(dx)<Math.abs(e2.getY()-e1.getY()))return false;if(dx>0){composeDialog(a);}else{try{Intent call=new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+Uri.encode(a)));startActivity(call);}catch(Exception ex){Toast.makeText(MainActivity.this,"تعذر فتح الاتصال لهذا الرقم",Toast.LENGTH_SHORT).show();}}return true;}});row.setOnTouchListener((v,event)->gestures.onTouchEvent(event));list.addView(row,rowLp);n++;}c.close();if(n==0)list.addView(tv("لا توجد محادثات في هذا القسم",18));}
void searchResults(String queryText){
 String q=queryText.toLowerCase(Locale.ROOT);
 list.setPadding(2,0,2,0);
 ArrayList<String[]> conversations=new ArrayList<>();
 CursorWrapper threads=new CursorWrapper(db.listThreads("all"));
 while(threads.moveToNext()){
  String address=threads.getString("address"),body=threads.getString("body"),status=threads.getString("status"),name=contactName(address);
  if(address.toLowerCase(Locale.ROOT).contains(q)||(body!=null&&body.toLowerCase(Locale.ROOT).contains(q))||name.toLowerCase(Locale.ROOT).contains(q))conversations.add(new String[]{address,body,status,name});
 }
 threads.close();
 addSearchSectionTitle("المحادثات", "عرض الكل", ()->{searchShowAllConversations=true;render();});
 int conversationLimit=searchShowAllConversations?conversations.size():Math.min(5,conversations.size());
 for(int i=0;i<conversationLimit;i++){
  String[] item=conversations.get(i);String address=item[0],body=item[1],name=item[3];
  LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(10,5,10,5);row.setBackground(rounded(Color.rgb(6,31,57),Color.rgb(20,81,116),16));
  TextView person=tv((name==null||name.isEmpty()?address:name+" · "+address),16);person.setTextColor(Color.rgb(8,217,245));TextView preview=tv(body==null?"":body,14);preview.setTextColor(Color.rgb(190,207,221));row.addView(person);row.addView(preview);
  LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=6;row.setOnClickListener(v->{Intent intent=new Intent(this,ConversationActivity.class);intent.putExtra("address",address);startActivity(intent);});row.setOnLongClickListener(v->{conversationOptions(v,address);return true;});list.addView(row,lp);
 }
 if(conversations.isEmpty())list.addView(tv("لا توجد محادثات مطابقة",14));
 addSearchSectionTitle("جهات الاتصال", "عرض الكل", ()->{searchShowAllContacts=true;render();});
 int matched=0,shown=0;HashSet<String> seen=new HashSet<>();
 try{
  android.database.Cursor contacts=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" COLLATE NOCASE ASC");
  if(contacts!=null){
   while(contacts.moveToNext()){
    String name=contacts.getString(0),number=contacts.getString(1);if(number==null||number.trim().isEmpty())continue;if(name==null)name="";
    if(!name.toLowerCase(Locale.ROOT).contains(q)&&!number.toLowerCase(Locale.ROOT).contains(q))continue;
    String key=number.replaceAll("[\\s()\\-]","");if(!seen.add(key))continue;matched++;
    if(!searchShowAllContacts&&shown>=5)continue;
    LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(10,5,10,5);row.setBackground(rounded(Color.rgb(6,31,57),Color.rgb(20,81,116),16));
    TextView person=tv(name.isEmpty()?number:name,16);person.setTextColor(Color.rgb(243,248,255));row.addView(person);if(!name.isEmpty())row.addView(tv(number,13));
    LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=6;row.setOnClickListener(v->{Intent intent=new Intent(this,ConversationActivity.class);intent.putExtra("address",number);startActivity(intent);});row.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle(name.isEmpty()?number:name).setItems(new String[]{"فتح المحادثة","إرسال رسالة"},(dlg,which)->{if(which==0){Intent intent=new Intent(this,ConversationActivity.class);intent.putExtra("address",number);startActivity(intent);}else composeDialog(number);}).show();return true;});list.addView(row,lp);shown++;
   }
   contacts.close();
  }
 }catch(Exception e){list.addView(tv("تعذّر تحميل جهات الاتصال. تحقق من إذن جهات الاتصال.",13));}
 if(matched==0)list.addView(tv("لا توجد جهات اتصال مطابقة",14));
}
void addSearchSectionTitle(String label,String action,Runnable onClick){
 LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.HORIZONTAL);header.setGravity(Gravity.CENTER_VERTICAL);header.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);
 TextView heading=tv(label,17);heading.setTypeface(Typeface.DEFAULT,Typeface.BOLD);heading.setTextColor(Color.rgb(243,248,255));header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));
 Button all=button(action);all.setTextSize(13);all.setPadding(8,2,8,2);all.setOnClickListener(v->onClick.run());header.addView(all,new LinearLayout.LayoutParams(-2,38));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=6;lp.bottomMargin=4;list.addView(header,lp);
}
int countUnreadForAddress(String address){android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM messages WHERE address=? AND type='in' AND read=0 AND trash=0",new String[]{address});try{return c.moveToFirst()?c.getInt(0):0;}finally{c.close();}}
 boolean hasFailedInThread(String address){android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM messages WHERE address=? AND trash=0 AND (status='failed' OR status='لم يتم الإرسال')",new String[]{address});try{return c.moveToFirst()&&c.getInt(0)>0;}finally{c.close();}}
 boolean isPinned(String address){android.database.Cursor c=db.getReadableDatabase().query("conversation_flags",new String[]{"pinned"},"address=?",new String[]{address},null,null,null);try{return c.moveToFirst()&&c.getInt(0)==1;}catch(Exception e){return false;}finally{c.close();}}
 void conversationOptions(View anchor,String address){
  PopupMenu menu=new PopupMenu(this,anchor);
  boolean archived="archived".equals(filter), blocked="blocked".equals(filter), pinned=isPinned(address);
  menu.getMenu().add("حذف إلى سلة المهملات");
  menu.getMenu().add("وضع علامة غير مقروءة");
  menu.getMenu().add(blocked?"إلغاء الحظر":"حظر");
  menu.getMenu().add(pinned?"إلغاء التثبيت":"تثبيت المحادثة");
  menu.getMenu().add(archived?"إلغاء الأرشفة":"أرشفة المحادثة");
  menu.getMenu().add("تحديد عدة محادثات");
  menu.setOnMenuItemClickListener(item->{
   String x=item.getTitle().toString();
   if(x.equals("حذف إلى سلة المهملات")){db.deleteThread(address);render();}
   else if(x.equals("وضع علامة غير مقروءة")){db.markThreadUnread(address);render();}
   else if(x.equals("حظر")||x.equals("إلغاء الحظر")){db.setConversationFlag(address,"blocked",x.equals("حظر"));render();}
   else if(x.equals("تثبيت المحادثة")||x.equals("إلغاء التثبيت")){db.setConversationFlag(address,"pinned",x.equals("تثبيت المحادثة"));render();}
   else if(x.equals("أرشفة المحادثة")||x.equals("إلغاء الأرشفة")){db.setConversationFlag(address,"archived",x.equals("أرشفة المحادثة"));render();}
   else if(x.equals("تحديد عدة محادثات")){selectingConversations=true;selectedConversations.clear();selectedConversations.add(address);render();}
   return true;
  });menu.show();
 }
 void selectedConversationMenu(View anchor){
  if(selectedConversations.isEmpty()){Toast.makeText(this,"حدد محادثة واحدة على الأقل",Toast.LENGTH_SHORT).show();return;}
  PopupMenu menu=new PopupMenu(this,anchor);menu.getMenu().add("حذف إلى سلة المهملات");menu.getMenu().add("وضع علامة غير مقروءة");menu.getMenu().add("حظر المحددة");menu.getMenu().add("تثبيت المحددة");menu.getMenu().add("أرشفة المحددة");
  menu.setOnMenuItemClickListener(item->{String x=item.getTitle().toString();ArrayList<String> chosen=new ArrayList<>(selectedConversations);
   if(x.equals("حذف إلى سلة المهملات"))new AlertDialog.Builder(this).setTitle("نقل المحادثات إلى المهملات").setMessage("سيتم نقل "+chosen.size()+" محادثة إلى سلة المهملات.").setNegativeButton("إلغاء",null).setPositiveButton("نقل",(d,w)->{for(String a:chosen)db.deleteThread(a);finishConversationSelection();}).show();
   else{for(String a:chosen){if(x.equals("وضع علامة غير مقروءة"))db.markThreadUnread(a);else if(x.equals("حظر المحددة"))db.setConversationFlag(a,"blocked",true);else if(x.equals("تثبيت المحددة"))db.setConversationFlag(a,"pinned",true);else if(x.equals("أرشفة المحددة"))db.setConversationFlag(a,"archived",true);}finishConversationSelection();}
   return true;
  });menu.show();
 }
 void finishConversationSelection(){selectingConversations=false;selectedConversations.clear();render();}
 void starredScreen(){list.addView(tv("الرسائل المميزة",22));list.addView(tv("تظهر هنا الرسائل التي وضعت عليها نجمة داخل المحادثات.",14));android.database.Cursor c=db.list("starred");int n=0;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),status=c.getString(c.getColumnIndexOrThrow("status"));if(!q.isEmpty()&&!a.toLowerCase(Locale.ROOT).contains(q)&&!body.toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.addView(tv("★  "+contactName(a)+"  ·  "+a,16));row.addView(tv(body,16));row.addView(tv(status,12));row.setOnClickListener(v->{Intent i=new Intent(this,ConversationActivity.class);i.putExtra("address",a);startActivity(i);});list.addView(row);View line=new View(this);line.setBackgroundColor(Color.rgb(20,81,116));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل مميزة حاليًا",17));}
